def solve(data):
    cutoff = data.get('cutoff', 10**9)
    selected = {}

    # Filter first, so an out-of-cutoff revision cannot replace an eligible one.
    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            key = ('id', event['id'])
            rank = (event.get('revision', 0), position)
            if key not in selected or rank >= selected[key][0]:
                selected[key] = (rank, event)
        else:
            selected[('anonymous', position)] = ((0, position), event)

    balances = dict(data.get('opening', {}))
    rounding = data['rounding']
    for _, event in selected.values():
        if event.get('void') is True:
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances[key] = balances.get(key, 0) + amount(event, rounding)

    return {'balances': balances}
